import{storedProjection}from"#harness/session-machine/view.js";import{addTokenUsage,usageSince}from"#shared/token-usage-math.js";const REPORTED_SESSION_USAGE_STATE_KEY=`eve.harness.reportedSessionUsage`,NO_USAGE={cacheReadTokens:0,cacheWriteTokens:0,inputTokens:0,outputTokens:0};function sessionUsage(e){return storedProjection(e.state).view.usage.total}function turnUsage(e,t){let n=NO_USAGE;for(let r of Object.values(e.runs)){if(r.usage===void 0)continue;let{owner:i}=r;(`turnId`in i?i.turnId:e.changes[i.changeId]?.turnId)===t&&(n=addTokenUsage(n,r.usage))}return n}function takeSessionUsageDelta(e){let t=sessionUsage(e);return{delta:usageSince(t,reportedUsage(e.state)),session:withReported(e,t)}}function markUsageReported(e,t){return withReported(e,addTokenUsage(reportedUsage(e.state),t))}function withModelUsage(e,t){return{...e,usage:{byKind:{model:t},total:t}}}function reportedUsage(e){return e?.[REPORTED_SESSION_USAGE_STATE_KEY]??NO_USAGE}function withReported(e,t){return{...e,state:{...e.state,[REPORTED_SESSION_USAGE_STATE_KEY]:t}}}export{NO_USAGE,markUsageReported,sessionUsage,takeSessionUsageDelta,turnUsage,withModelUsage};